\begin{theorem}[norm_cos_eq]
Show that $|\cos z| = \sqrt{\sinh^2 y + \cos^2 x}$.
\end{theorem}

\begin{proof}
\[
\begin{aligned}
|\cos z| &= |\cos x \cosh y - i \sin x \sinh y| \\
&= \sqrt{\cos^2 x \cosh^2 y + \sin^2 x \sinh^2 y} \\
&= \sqrt{\cos^2 x (1 + \sinh^2 y) + \sin^2 x \sinh^2 y} \\
&= \sqrt{\cos^2 x + \sinh^2 y (\cos^2 x + \sin^2 x)} \\
&= \sqrt{\cos^2 x + \sinh^2 y}
\end{aligned}
\]
\end{proof}

\begin{theorem}[MeasureTheory.Integrable.fourierInv_fourier_eq] Let $f$ be an integrable function on a finite-dimensional real inner product space. If its Fourier transform $\mathcal{F} f$ is also integrable, then at every point where $f$ is continuous, the inverse Fourier transform of $\mathcal{F} f$ equals $f$ itself; that is, $\mathcal{F}^{-1}(\mathcal{F} f)(v) = f(v)$ for all continuity
 points $v$ of $f$.
\end{theorem}

\begin{theorem}[exists_seq_finite_rank_strongly_convergent_to]
Consider a separable Hilbert space $\mathcal{H}$.
Show that for any bounded operator $T$ there is a sequence $\{T_n\}$ of bounded operators of finite rank so that $T_n \to T$ strongly as $n \to \infty$.
\end{theorem}

\begin{proof}
Let $(g_k)_{k=1}^{\infty}$ be a orthonormal basis of $\mathcal{H}$. Let $T_n g_k = T g_k$ for $k \le n$ and $T_n g_k = 0$ for $k > n$. Then each $T_n$ has finite rank (i.e. dimension of range is finite) and $\|T_n g_k - T g_k\| = 0$ for $n$ sufficiently large. For an arbitrary vector $g$, applying the triangle inequality gives $\|T_n g - T g\| = 0$ for $n$ sufficiently large.
\end{proof}

