\begin{theorem}[open_disc_not_disjoint_union_rectangles]
An open disc in $\mathbb{R}^2$ is not the disjoint union of open rectangles. \\
\end{theorem}

\begin{theorem}[convexOn_sq_div]
Suppose that $f : \mathbb{R}^n \to \mathbb{R}$ is nonnegative and convex, and $g : \mathbb{R}^n \to \mathbb{R}$ is positive and concave. Show that the function $f^2/g$, with domain $\mathbf{dom} f \cap \mathbf{dom} g$, is convex.
\end{theorem}

\begin{proof}
Consider the function $h : \mathbb{R} \times \mathbb{R}_{++} \to \mathbb{R}$ defined by $h(x, y) = x^2 / y$. 
It is easy to show that the quadratic-over-linear function $h$ is convex.

Furthermore, we observe the monotonicity properties of $h(x, y)$ on the restricted domain where $x \ge 0$ and $y > 0$:
\begin{itemize}
    \item $h$ is non-decreasing in $x$, because $\frac{\partial h}{\partial x} = \frac{2x}{y} \ge 0$.
    \item $h$ is non-increasing in $y$, because $\frac{\partial h}{\partial y} = -\frac{x^2}{y^2} \le 0$.
\end{itemize}

Now, consider the composition $h(f(z), g(z)) = f(z)^2 / g(z)$. 
By the assumptions, $f(z) \ge 0$ and $g(z) > 0$ for all $z \in \mathbf{dom} f \cap \mathbf{dom} g$, meaning the outputs of $f$ and $g$ always fall into the region where the above monotonicity properties hold.

We can apply the composition rule: since $f$ is convex, $g$ is concave, and the outer function $h$ is convex, non-decreasing in its first argument, and non-increasing in its second argument (on the range of the inner functions), the composition $h(f(z), g(z))$ is convex.

Therefore, $f^2/g$ is convex.
\end{proof}

\begin{theorem}[integral_cos_sq_tendsto_half_measure]
If $f$ is integrable on $[0, 2\pi]$, then $\int_0^{2\pi} f(x) e^{-inx} dx \to 0$ as $|n| \to \infty$. Show as a consequence that if $E$ is a measurable subset of $[0, 2\pi]$, then
\[ \int_E \cos^2(nx + u_n) dx \to \frac{m(E)}{2}, \quad \text{as } n \to \infty \]
for any sequence $\{u_n\}$.
\end{theorem}

\begin{proof}
First, note that $\int_0^{2\pi} f(x) \cos(nx) dx \to 0$ and $\int_0^{2\pi} f(x) \sin(nx) \to 0$ since these are the real and imaginary parts of $\int_0^{2\pi} f(x) e^{-inx} dx$. In particular, if we let $f(x) = \chi_E(x)$ for some measurable $E \subset [0, 2\pi]$, then for any $\epsilon > 0$, $\exists N$ such that $\left| \int_0^{2\pi} \chi_E(x) \sin(nx) dx \right|$ and $\left| \int_0^{2\pi} \chi_E(x) \cos(nx) dx \right|$ are both less than $\frac{\epsilon}{2}$ provided $|n| > N$. Then for any sequence $u_n$,
\begin{align*}
\left| \int_E \cos(2nx + 2u_n) dx \right| &= \left| \int_E \cos(2nx) \cos(2u_n) - \sin(2nx) \sin(2u_n) dx \right| \\
&= \left| \cos(2u_n) \int_0^{2\pi} \chi_E(x) \cos(2nx) dx - \sin(2u_n) \int_0^{2\pi} \chi_E(x) \sin(2nx) dx \right| \\
&\le |\cos(2u_n)| \left| \int_0^{2\pi} \chi_E(x) \cos(2nx) dx \right| + |\sin(2u_n)| \left| \int_0^{2\pi} \chi_E(x) \sin(2nx) dx \right| \\
&\le 1 \cdot \frac{\epsilon}{2} + 1 \cdot \frac{\epsilon}{2} = \epsilon
\end{align*}
for $|n| > N$. Hence $\int_E \cos(2nx + 2u_n) dx \to 0$ as $|n| \to \infty$. Now
\begin{align*}
\int_E \cos^2(nx + u_n) dx &= \int_E \frac{1}{2} (1 + \cos(2(nx + u_n))) dx \\
&= \frac{m(E)}{2} + \frac{1}{2} \int_0^{2\pi} \chi_E(x) \cos(2nx + 2u_n) dx
\end{align*}
and we have shown that the second term tends to $0$ as $|n| \to \infty$. \qed
\end{proof}

\begin{theorem}[IsQuasiSeparated.image_of_isEmbedding]
Let $S \subseteq X$ be a quasiseparated set and $h:X \to Y$ is a topological embedding. Then, $f(S)$ is quasiseparated.
\end{theorem}

\begin{proof}
Let $U,V$ be compact open subsets of $f(S)$. Since $f$ is an embedding, $f^{-1}(U), f^{-1}(V)$ are compact open subsets of $S$. Then $f^{-1}(U) \cap f^{-1}(V)$ is compact since $S$ is quasiseparated. Hence, $U \cap V = f(f^{-1}(U) \cap f^{-1}(V))$ is compact and thus $f(S)$ is quasiseparated.

\begin{definition}[paths_homotopic]
A topological space $X$ is simply connected if its fundamental groupoid is equivalent to the the groupoid with one object and the identity morphism.
\end{definition}

\begin{theorem}[simply_connected_iff_paths_homotopic]
A topological space is simply connected if and only if it is path connected, and there is at most one path up to homotopy between any two points.
\end{theorem}
\begin{proof}
Let $X$ be a simply connected space. The fundamental groupoid $\Pi X$ being equivalent to a groupoid $\mathcal{E}$ with one object $e$ and the identity morphism, is equivalent to being a groupoid having a unique morphism between any two objects. It is equivalent to say that any two points of $X$ have a unique path between them up to homotopy equivalence. In partiular, $X$ is path connected in such case.
\end{proof}

\begin{definition}[stalkToFiber_injective]
	Let $X$ be a topological space and $\mathcal{F}$ a presheaf of sets on $X$. Let $\widetilde{\mathcal{F}}$ be the presheaf 
\begin{align*}
U \mapsto \{(s_x)_{x \in U} \in \prod_{x \in U} \mathcal{F}_x  \text{ such that $(*)$.}\}
\end{align*}
where $(*)$ is the property that for any $x \in U$, there exists an open neighborhood $V \subseteq U$ of $x$, and a section $s \in \mathcal{F}(V)$ such that $s_y = (V,s) \in \mathcal{F}_y$ for all $y \in V$. Then $\widetilde{\mathcal{F}}$ is a sheaf and is called the sheafification of the presheaf $\mathcal{F}$.
\end{definition}

\begin{theorem}[sheafifyStalkIso]
	Let $X$ be a topological space and $\mathcal{F}$ a presheaf of sets on $X$. Let $\widetilde{\mathcal{F}}$ be the sheafification of $\mathcal{F}$. For $x \in X$, an obvious map
\begin{align*}
	\phi_x: \widetilde{\mathcal{F}}_x \to \mathcal{F}_x, \quad (U,s) \mapsto s(x)
\end{align*}
is an isomorphism of stalks $\widetilde{\mathcal{F}}_x$ and $\mathcal{F}_x$.
\end{theorem}

\begin{proof}
We prove the surjectivity first. Let $(U,s) \in \mathcal{F}_x$ be given where $U$ is an open neighborhood of $x$ and $s \in \mathcal{F}(U)$. Then, $t:=(s_y)_{y \in U} \in \widetilde{F}(U)$ and we have $(U,t) \in \widetilde{F}_x$ which is mapped to $(U,s)$ under $\phi_x$ since $t(x) = s_x = (U,s)$.

For injectivity, suppose we have $(U,s), (V,t) \in \widetilde{\mathcal{F}}_x$ such that $s(x) = t(x)$. By definition of the sheafification, there exist open neighborhoods $U’\subseteq U$,$V’\subseteq V$ of $x$ and sections $s’ \in \mathcal{F}(U’)$, $t’ \in \mathcal{F}(V’)$ such that $s’_y = s(y)$ for all $y \in U’$ and $t’_z = t(z)$ for all $z \in V’$. Thus, we have
\begin{align*}
(U’,s’) = s’_x = s(x) = t(x) = t’_x = (V’,t’)
\end{align*}
and it follows that there exists an open neighborhood $W \subseteq U’ \cap V’$ of $x$ such that $s’|_W = t’|_W$. Then, for any $y \in W$, we have
\begin{align*}
	s(y) = s’_y = (W,s’) = (W,t’) = t’_y = t(y)
\end{align*}
that is, two sections $s,t$ of $\widetilde{\mathcal{F}}$ agree on $W$. Therefore, we have
\begin{align*}
	(U,s) = (W,s|_W) = (W,t|_W) = (V,s)
\end{align*}
and the map $\phi_x$ is injective.
\end{proof}

\begin{definition}[Trivialization.pullback_linear]
Let $E$ be a vector bundle over a base space $B$ with fiber $F$, where $F$ is a normed space over a normed field $k$. Given a continuous map $f: B' \to B$, the pullback bundle $f^*E$ is defined to be a vector bundle over $B'$ whose fiber $(f^*E)_x$ is defined as $E_{f(x)}$ for each $x \in B'$. It is a disjoint union $\bigsqcup_{x \in B'} (f^*E)_x$ of all these fibers equipped with the coarsest topology for which both the projections $\pi'$ to the base $B'$ and $f'$ to the original bundle $E$
\begin{align*}
    \pi': f^*E \to B', \quad (x,v) \mapsto x, \quad f':f^*E \to E, \quad (x,v) \mapsto v, \quad x \in B',\, v \in (f^*E)_x
\end{align*}
are continuous.
\end{definition}

\begin{theorem}[VectorBundle.pullback]
Given a vector bundle $E$ over a base space $B$ with fiber $F$ and a continuous map $f:B' \to B$, the pullback bundle $f^*E$ over $B'$ inherits the structure of a vector bundle.
\end{theorem}
\begin{proof}
Let $\pi:E \to B$ be a vector bundle with fiber $F$, a normed space over a normed field $k$, and let $f: B' \to B$ be a continuous map. We aim to show that the pullback bundle $ \pi':f^*E \to B'$ is naturally a vector bundle.

For each $x \in B'$, the fiber $(f^*E)_x$ is defined as $E_{f(x)}$. Since $E_{f(x)}$ is a vector space over $k$, the fiber $(f^*E)_x$ inherits the same vector space structure.

Let $e$ be a local trivialization of $E$ over an open set $U \subseteq B$. That is, $e: E|_U \xrightarrow{\simeq} U \times F$ is a homeomorphism such that $\pi = p \circ e$ where $p: U \times F \to U$ is the projection, and $e|_{E_x}: E_x \xrightarrow{\simeq} F$ is a linear isomorphism. The pullback of $ e $ along $ f $ gives a local trivialization 
\begin{align*}
	f^*e:= (f^*E)|_{f^{-1}(U)} \xrightarrow{\simeq} f^{-1}(U) \times F, \quad (x,v) \mapsto (x,e|_{E_{f(x)}}(v)), \quad x \in f^{-1}(U), \, v \in E_{f(x)}
\end{align*}
Then, each $(f^*e)|_{E_x} = e|_{E_{f(x)}}$ is a linear isomorphism as desired.

The transition maps for $f^*E$ are obtained by pulling back the transition maps of $ E $ along $ f $. Explicitly, given two trivializations $e_U:E|_U \xrightarrow{\simeq} U \times F$, $e_V:E|_V \xrightarrow{\simeq} V \times F$ for open subsets $U,V \subseteq B$, we have 
\begin{align*}
	(U \cap V) \times F \xrightarrow[e_U^{-1}]{\simeq} E|_{U \cap V} \xrightarrow[e_V]{\simeq} (U \cap V) \times F, \quad (x,a) \mapsto (e_U|_{E_x})^{-1}(a) \mapsto (x,(e_V|_{E_x} \circ (e_U|_{E_x})^{-1})(a))
\end{align*}
and transition map $g_{UV}: U \cap V \to \text{GL}(F)$ is defined to be
\begin{align*}
	g_{UV}(x) = e_V|_{E_x} \circ (e_U|_{E_x})^{-1}, \quad x \in U \cap V.
\end{align*}
Then, the transition maps of the pullback bundle $f^*E$ are of the form
\begin{align*}
	(f^*g)_{f^{-1}(U) f^{-}(V)}(x) &= (f^*e)_{f^{-1}(V)}|_{(f^*E)_x} \circ ((f^*e)_{f^{-1}(U)}|_{(f^*E)_x})^{-1}, \quad x \in f^{-1}(U) \cap f^{-1}(V) \\
    &= e_V|_{E_{f(x)}} \circ (e_U|_{E_{f(x)}})^{-1} \\
    &= g_{UV}(f(x))
\end{align*}
That is, we have
\begin{align*}
    (f^*g)_{f^{-1}(U) f^{-}(V)} = g_{UV} \circ f.
\end{align*}
Since $f$ is continuous, transition maps of $f^*E$ are continuous and define a linear automorphism of $F$ for each $x \in B'$. Therefore, $f^*E$ inherits the natural structure of a vector bundle.
\end{proof}

\begin{definition}[continuousLinearMap]
    Let $E_1$, $E_2$ be vector bundles over a base space $B$ with fibers $F_1$, $F_2$, respectively, where $F_i$ is a normed space over a normed field $k_i$, for $i=1,2$. Let $\sigma: k_1 \to k_2$ be an isometric ring homomorphism. The Hom-bundle $\text{Hom}_\sigma (E_1,E_2)$ is defined to be a vector bundle over $B$ whose fiber $\text{Hom}_\sigma (E_1,E_2)_x$ is defined as the space of $\sigma$-semilinear maps between $(E_1)_x$ and $(E_2)_x$.
\end{definition}

\begin{theorem}[Bundle.ContinuousLinearMap.vectorBundle]
     Let $E_1$, $E_2$ be vector bundles over a base space $B$ with fibers $F_1$, $F_2$, respectively, where $F_i$ is a normed space over a normed field $k_i$, for $i=1,2$. Let $\sigma: k_1 \to k_2$ be an isometric ring homomorphism. The Hom-bundle $\text{Hom}_\sigma (E_1,E_2)$ inherits the natural structure of a vector bundle.
\end{theorem}
\begin{proof}
    For each $x \in B$, the fiber $\text{Hom}_\sigma(E_1,E_2)_x$ is the space of $\sigma$-semilinear maps between $(E_1)_x$ and $(E_2)_x$. There exist an operator norm of semilinear maps and a scalar multiplication
    \begin{align*}
        (a \cdot f)(m) = a \cdot f(m), \quad a \in k_2,\, f \in \text{Hom}_\sigma(E_1,E_2)_x, \,m \in (E_1)_x
    \end{align*}
    so that $\text{Hom}_\sigma(E_1,E_2)_x$ has the natural structure of a normed space over $k_2$.

    Now we define local trivializations. Let 
    \begin{align*}
        e_1:E_1|_{U_1} \xrightarrow{\simeq} U_1 \times F_1, \quad e_2: E_2|_{U_2} \xrightarrow{\simeq} U_2 \times F_2
    \end{align*}
    be local trivializations of $E_1,E_2$, respectively, for open subsets $U_1,U_2 \subseteq B$. Then we define a local trivialization of the Hom-bundle over $U:= U_1 \cap U_2$ by
    \begin{align*}
        e: \text{Hom}_\sigma(E_1,E_2)|_U \xrightarrow{\simeq} U \times \text{Hom}_\sigma(F_1,F_2), \quad (x,T) \mapsto (x,(e_2)_x \circ T \circ (e_1)_x^{-1})
    \end{align*}
    for $x \in B$, $T \in \text{Hom}_\sigma(E_1,E_2)_x$, where $(e_i)_x=e_i|_{(E_i)_x}: (E_i)_x \xrightarrow{\simeq} F_i$, $i=1,2$ are linear isomorphisms. 

    For transition maps, let $e,e'$ be local trivializations of the Hom-bundle over $U,U'$, respectively, which are induced by the pairs of local trivializations $(e_1,e_2),(e_1',e_2')$. For each $i=1,2$, we have transition maps
    \begin{align*}
        g_i: U_i \cap U_i' \to \text{GL}(F_i)
    \end{align*} 
    where $g_i$ is induced from the composition
    \begin{align*}
        (U_i \cap U_i') \times F_i \xrightarrow[e_i^{-1}]{\simeq} E_i|_{U_i \cap U_i'} \xrightarrow[e_i]{\simeq} (U_i \cap U_i') \times F_i
    \end{align*}
    of the bundle $E_i$. Now for the Hom-bundle, define the transition map as
    \begin{align*}
        g: U \cap U' \to \text{GL}(\text{Hom}_\sigma(F_1,F_2)), \quad x \mapsto (S \mapsto g_2(x) \circ S \circ g_1(x)^{-1})
    \end{align*}
    By construction, local trivializations and transition maps of the Hom-bundle above are continuous and define the natural vector bundle structure on the Hom-bundle.
\end{proof}

\begin{definition}[skyscraperPresheaf_eq_pushforward]
    Let $X$ be a topological space. $p_0 \in X$. Let $\mathcal{C}$ be a category with a terminal object and $A \in \text{Ob}(\mathcal{C})$ be an object of $\mathcal{C}$. A skyscraper sheaf $\mathcal{F}$ with value $A$ is a presheaf on $X$ with values in $\mathcal{C}$ such that
    $\mathcal{F}(U) = A$ if $p_0 \in U$ and $\mathcal{F}(U) = 1_\mathcal{C}$ if $p_0 \notin U$ where $1_\mathcal{C}$ is some terminal object of $\mathcal{C}$.
\end{definition}

\begin{theorem}[skyscraperPresheaf_isSheaf]
    A skyscraper presheaf with value $A$ is a sheaf.
\end{theorem}
\begin{proof}
    Consider the obvious continuous map $f: * \to X$ from the one-point space to $X$ such that $f(*) = p_0$. Let $\mathcal{F}$ be a skyscraper presheaf on $X$ at $p_0$ with value $A$, and $\mathcal{G}$ a skyscraper presheaf on $*$ with value $A$. We claim that
    \begin{align*}
        \mathcal{F} = f_*\mathcal{G}
    \end{align*}
    Indeed, for an open set $U \subseteq X$, we have
    \begin{align*}
        (f_*\mathcal{G})(U) = \mathcal{G}(f^{-1}(U)) = \mathcal{G}(*) = A, \quad p_0 \in U \\
        (f_*\mathcal{G})(U) = \mathcal{G}(f^{-1}(U)) = \mathcal{G}(\emptyset) = 1_\mathcal{C}, \quad p_0 \notin U
    \end{align*}
    so that $\mathcal{F} = f_*\mathcal{G}$.

    Note that on the one-point space, a presheaf is a sheaf if and only if its value at empty set is a terminal object. Hence, a skyscraper presheaf $\mathcal{G}$ is a sheaf on $*$. Meanwhile, since the pushforward of a sheaf is a sheaf, $\mathcal{F} = f_*\mathcal{G}$ is a sheaf on $X$ as well.
\end{proof}

\begin{definition}[IsLocallySurjective]
A map of presheaves \( T : \mathcal{F} \to \mathcal{G} \) is \emph{locally surjective} if for every open set \( U \), every section \( t \in \mathcal{G}(U) \), and every point \( x \in U \), there exists an open set \( V \) such that \( x \in V \subseteq U \) and a section \( s \in \mathcal{F}(V) \) such that \( T(s) = t|_V \).
\end{definition}

\begin{theorem}[locally_surjective_iff_surjective_on_stalks]
A morphism \( T : \mathcal{F} \to \mathcal{G} \) of presheaves is locally surjective if and only if for every point \( x \in X \), the induced map on stalks \( \mathcal{F}_x \to \mathcal{G}_x \) is surjective.
\end{theorem}
\begin{proof}
Suppose \( T \) is locally surjective. Let \( x \in X \) and let \( g \in \mathcal{G}_x \) be a germ. Represent \( g \) as \( \langle t, U \rangle \) for some open set \( U \subseteq X \) containing \( x \) and some section \( t \in \mathcal{G}(U) \). By local surjectivity, there exists an open set \( V \subseteq U \) containing \( x \) and a section \( s \in \mathcal{F}(V) \) such that \( T(s) = t|_V \). The germ of \( s \) at \( x \) maps to \( \langle t|_V ,V \rangle = g \), proving surjectivity on stalks.

Conversely, suppose that for every \( x \in X \), the induced map on stalks is surjective. Let \( U \subseteq X \) be an open set, \( t \in \mathcal{G}(U) \), and \( x \in U \). The germ \( t_x \) of \( t \) at \( x \) is in \( \mathcal{G}_x \), so by surjectivity, there exists a germ \( s_x \in \mathcal{F}_x \) mapping to \( t_x \). Represent \( s_x \) as \( \langle s, V \rangle \) for some open \( V \subseteq X \) containing \( x \) and some \( s \in \mathcal{F}(V) \). There exists an open set \( W \subseteq V \cap U \) containing \( x \) such that \( T(s)|_W = t|_W \). Thus, \( T \) is locally surjective.
\end{proof}

\begin{definition}[singularChainComplexFunctor_exactAt_of_totallyDisconnectedSpace]
    Given a preadditive category $C$ with coproducts and homology, the singular chain complex functor is the functor
    \begin{align*}
        C_\bullet(-;-): C \to \text{Fun}(\textbf{Top}, \textbf{Ch}_{\ge 0}(C)),\quad R \mapsto (X \to C_\bullet(X;R))
    \end{align*}
    from $C$ to the category of functors from the category $\textbf{Top}$ of topological spaces and the category $\textbf{Ch}_{\ge 0}(C)$ of chain complexes in $C$ defined as follows. Given a topological space $X$, we have an associated simplicial set $\text{Sing}(X) = \{\text{Sing}(X)_n\}$ where $\text{Sing}(X)_n$ is the set of singular $n$-simplices, that is, continuous maps from the standard $n$-simplex $\Delta_n$ to $X$. For each $n =0,1,2,\cdots$, the $i$-th face map $d_i^n:X_n \to X_{n-1}$ maps the singular $n$-simplex $\sigma$ to its restriction to the $i$-th face of $\Delta_n$ which is the set of points of $\Delta_n$ whose $i$-th coordinate is $0$. Then $C_\bullet(X;R)$ is the chain complex with
    \begin{align*}
        C_n(X;R) = \coprod_{X_n} R, \quad d_n:C_n(X;R) \to C_{n-1}(X;R),\,\, d_n = \sum_{i=0}^n (-1)^i d_i^n
    \end{align*}
\end{definition}

\begin{definition}[isZero_singularHomologyFunctor_of_totallyDisconnectedSpace]
    Let $C$ be a preadditive category wth coproducts and homology. Then the singular homology functor is the functor
    \begin{align*}
        H_\bullet(-;-):C \to \text{Fun}(\textbf{Top},\textbf{Ch}_{\ge 0}(C)), R \mapsto (X \mapsto H_\bullet(X;R))
    \end{align*}
    where $H_n(X;R)$ is the $n$-th homology of the chain complex $C_\bullet(X;R)$.
\end{definition}

\begin{theorem}[singularHomologyFunctorZeroOfTotallyDisconnectedSpace]
    Let $X$ be a totally disconnected topological space, $C$ a preadditive category with coproducts and homology, and $R$ an object of $C$. Then the singular homology of $X$ with coefficients in $R$ is given by
    \begin{align*}
        H_n(X;R) = \begin{cases}
            \coprod_{x \in X} R, &\text{ if }n = 0\\
            0, &\text{ if } n > 0
        \end{cases} 
    \end{align*}
\end{theorem}
\begin{proof}
    Since $X$ is totally disconnected, any singleton of $X$ is open. So any continuous map from a connected space is constant. Hence, any singular $n$-simplex of $X$ is a constant map, and we have identification $\text{Sing}(X)_n \simeq X$, $\sigma \mapsto \text{Im}(\sigma)$. Moreover, face maps $d_i^n$ are just restrictions of singular simplices, so they are all the identity map $X \to X$ under the identifications $\text{Sing}(X)_n \simeq X \simeq \text{Sing}(X)_{n-1}$. Thus, we have
    \begin{align*}
        d_n = \sum_{i=0}^n (-1)^nd_i^n = \begin{cases}
            0, &\text{if } n= \text{ even} \\
            \text{id}, &\text{if } n= \text{ odd}
        \end{cases}
    \end{align*}
    and the singular chain complex $C_\bullet(X;R)$ is of the form
    \begin{align*}
        \coprod_{x \in X} R \xleftarrow{0} \coprod_{x \in X} R \xleftarrow{\text{id}} \coprod_{x \in X} R \xleftarrow{0} \cdots
    \end{align*}
    THerefore, we have
    \begin{align*}
        H_n(X;R) = \begin{cases}
            \coprod_{x \in X} R, &\text{ if }n = 0\\
            0, &\text{ if } n > 0
        \end{cases} 
    \end{align*}
\end{proof}

\begin{definition}[normalizedMooreComplex]
Let $C$ be an abelian category. We define the normalized Moore complex to be a functor
\begin{align*}
    N_\bullet: \mathbf{sC} \to \mathbf{Ch}_{\ge 0}(C), \quad X \mapsto N_\bullet(X)
\end{align*}
from the category $\mathbf{sC}$ of simplicial objects of $C$ to the category $\mathbf{Ch}_{\ge 0}(C)$ of chain complexes in $C$ where
\begin{align*}
    N_n(X) = \begin{cases}
        X_0, &\text{for $n=0$}\\
        \bigcap_{i=1}^n \ker (d_i^n:X_n \to X_{n-1}), &\text{for $n > 0$}
    \end{cases}
\end{align*}
where $d_i^n:X_n \to X_{n-1}$ is the $i$-th face map. The differentials are defined to be $d_n := d_0^n|_{N_n(X)}:N_n(X) \to N_{n-1}(X)$ where $d_0^n:X_n \to X_{n-1}$ is the $0$-th face map. For a morphism $f:X \to Y$ in the category $\mathbf{sC}$, we define $N_\bullet(f):N_\bullet(X) \to N_\bullet(Y)$ by $N_n(f):=f_n|_{N_n(X)}:N_n(X) \to N_n(Y)$.
\end{definition}
\begin{theorem}[normalizedMooreComplex_objD]
    $N_\bullet$ is a well-defined functor.
\end{theorem}
\begin{proof}
    We first show that it is well-defined on objects. That is, for each simplicial object $X$ in $C$, the sequence $N_\bullet(X)$ together with $d_\bullet$ is a chain complex. It suffices to prove that for each $n=1,2,\cdots$, $d_n:N_n(X) \to N_{n-1}(X)$ is well-defined and $d_{n-1} \circ d_n$ is the zero map.

    For well-definedness, it suffices to check $d_i^{n-1} \circ d_0^n|_{N_n(X)} : N_n(X) \to X_{n-1} \to X_{n-2}=0$ for all $i=1,2,\cdots,n-1$. Indeed, by simplicial identities, we have
    \begin{align*}
        d_i^{n-1} \circ d_0^n|_{N_n(X)} = d_0^{n-1} \circ d_{i+1}^n|_{N_n(X)} = 0 
    \end{align*}
    by construction of $N_n(X)$. Similarly, we have
    \begin{align*}
        d_{n-1} \circ d_n = d_0^{n-1} \circ d_0^n|_{N_n(X)} = d_0^{n-1} \circ d_1^n|_{N_n(X)} = 0.
    \end{align*}

    Now we prove that $N_\bullet$ is well-defined on morphisms. A morphism $f:X \to Y$ in the category $\mathbf{sC}$ is a collection of morphisms $f_n:X_n \to Y_n$ in the category $C$ compatible with face maps of $X$ and $Y$. That is, we have $f_{n-1} \circ d_i^n = d_i^n \circ f_n$ for all $n \ge 0$. Then, for all $i=1,\cdots,n$,
    \[
    d_i^n \circ N_n(f) = d_i^n \circ f_n|_{N_n(X)} = f_{n-1} \circ d_i^n |_{N_n(X)} = 0
    \]
    so that $f_n|_{N_n(X)}: N_n(X) \to Y_n$ factors through $N_n(Y)$ so that $N_n(f)$ is a well-defined morphism $N_n(X) \to N_n(Y)$.
\end{proof}

\begin{definition}[alternatingFaceMapComplex]
    Let $C$ be a preadditive category. We define alternating face map complex to be a functor
    \[
        C_\bullet: \mathbf{sC} \to \mathbf{Ch}_{\ge 0}(C), \quad X \mapsto C_\bullet(X)
    \]
    from the category $\mathbf{sC}$ of simplicial objects of $C$ to the category $\mathbf{Ch}_{\ge 0}(C)$ of chain complexes in $C$ where $C_n(X) = X_n$ for each $n=0,1,\cdots$, and the differentials $d_n:C_n(X) \to C_{n-1}(X)$ are defined by
    \begin{align*}
        d_n = \sum_{i=0}^n (-1)^n d_i^n
    \end{align*}
    where $d_i^n:X_n \to X_{n-1}$ is the $i$-th face map. For a morphism $f:X \to Y$ of simplicial objects, we define $C_\bullet(f):C_\bullet(X) \to C_\bullet(Y)$ by $C_n(f) = f_n$ for all $n$.
\end{definition}

\begin{theorem}[map_f]
    The functor $C_\bullet$ is a well-defined functor.
\end{theorem}
\begin{proof}
    We first show that it is well-defined on objects. That is, for each simplicial object $X$ of $C$, the sequence $C_\bullet(X)$ together with $d_\bullet$ is a chain complex. It suffices to show that $d_{n-1}\circ d_n = 0$ for all $n=1,2,\cdots$, and we have
    \begin{align*}
        d_{n-1} \circ d_n &= \sum_{i=0}^{n-1} \sum_{j=0}^n (-1)^{i+j} d_i^{n-1} \circ d_j^n \\
        &= \sum_{i < j} (-1)^{i+j} d_i^{n-1} \circ d_j^n + \sum_{i \ge j} (-1)^{i+j} d_i^{n-1} \circ d_j^n \\
        &= \sum_{i < j} (-1)^{i+j} d_{j-1}^{n-1} \circ d_i^n + \sum_{i \ge j} (-1)^{i+j} d_i^{n-1} \circ d_j^n \\
        &= \sum_{i \le j'} (-1)^{i+j'+1} d_{j'}^{n-1} \circ d_i^n + \sum_{i \ge j} (-1)^{i+j} d_i^{n-1} \circ d_j^n \\
        &= 0.
    \end{align*}
    For a morphism $f: X \to Y$, $f_n$'s commute with the face maps of $X$ and $Y$, and hence $f$ is compatible with the differentials of $C_\bullet(X)$ and $C_\bullet(Y)$. That is, $f_{n-1} \circ d_n = d_n \circ f_n$ for each $n$, and thus $C_\bullet(f)$ is a well-defined morphism from $C_\bullet(X)$ to $C_\bullet(Y)$
\end{proof}

\begin{theorem}[inclusionOfMooreComplex]
    Let $C$ be an abelian category. Then there is an inclusion $N_\bullet \hookrightarrow C_\bullet $ from the normalized Moore complex into the alternating face map complex, as a natural transformation of functors.
\end{theorem}
\begin{proof}
    We define the map of functors $i:N_\bullet \to C_\bullet$ as follows. For a simplicial object $X$ in $C$ and for each $n=0,1,2,\cdots$, we have a natural inclusion
    \begin{align*}
        i_n: N_n(X) = \bigcup_{i=0}^n \ker(d_i^n:X_n \to X_{n-1}) \hookrightarrow X_n=C_n(X).
    \end{align*}
    To show that they induce an inclusion of chain complexes, it suffices to show that the inclusions above commute with the differentials. Indeed, denote the differentials of $N_\bullet(X)$, $C_\bullet(X)$ by $d_\bullet^N$, $d_\bullet^C$, respectively. Then, we have
    \begin{align*}
        d_n^C \circ i_n = i_n \circ \sum_{i=0}^n d_i^n|_{N_n(X)} = i_n \circ d_0^n|_{N_n(X)} = i_n \circ d_n^N
    \end{align*}
    since $N_n(X) \subseteq \ker d_i^n$ for all $i=1,2,\cdots,n$. Therefore, we have an inclusion of chain complexes $i_X: N_\bullet(X) \hookrightarrow C_\bullet(X)$ with $(i_X)_n:= i_n:N_n(X) \hookrightarrow C_n(X)$. 

    Moreover, this inclusion defines a natural transformation since for any other simplicial object $Y$ in $C$ and a morphism $f:X \to Y$ of simplicial objects, we have $i_Y \circ N_\bullet(f) = C_\bullet(f) \circ i_X$ by construction.
\end{proof}

\begin{theorem}[isTotallyDisconnected_cantorSet]
Prove that the Cantor set $\mathcal{C}$ is totally disconnected and perfect. 
\end{theorem}

\begin{proof}
Let $X = \{0, 1\}^\mathbb{N}$ be the space of infinite sequences of $0$s and $1$s, equipped with the product topology (where $\{0, 1\}$ has the discrete topology). It is a standard result in topology that the Cantor set $\mathcal{C}$ is homeomorphic to $X$ via a map $e: \mathcal{C} \to X$. We use this homeomorphism to prove the required properties.

\paragraph{1. Perfect:}
A set is perfect if it is closed and has no isolated points.
\begin{itemize}
    \item \textbf{Closed:} The space $X = \{0, 1\}^\mathbb{N}$ is a product of compact spaces, so it is compact by Tychonoff's theorem. Since $X$ is a compact subset of a Hausdorff space, it is closed. Since $\mathcal{C} \cong X$, $\mathcal{C}$ is also closed in $\mathbb{R}$.

    \item \textbf{No isolated points:} Let $x \in \mathcal{C}$ be any point and $U$ be an arbitrary open neighborhood of $x$. We must show there exists $z \in U \cap \mathcal{C}$ such that $z \neq x$.
    Through the homeomorphism $e$, $e(x)$ is a sequence $(s_1, s_2, \dots)$. By the definition of the product topology, there exists a "cylinder set" $W \subset e(U)$ such that:
    \[ W = \{ (y_i) \in X : y_1 = s_1, y_2 = s_2, \dots, y_n = s_n \} \]
    for some finite $n$. Now, define a new sequence $y = (y_i)$ such that:
    \[ y_i = 
    \begin{cases} 
    s_i & \text{if } i \neq n+1 \\
    1 - s_i & \text{if } i = n+1 
    \end{cases} \]
    Since $y$ matches the first $n$ bits of $e(x)$, we have $y \in W \subset e(U)$. However, $y \neq e(x)$ because the $(n+1)$-th bit is different. Letting $z = e^{-1}(y)$, we have $z \in U \cap \mathcal{C}$ and $z \neq x$. Thus, $x$ is not an isolated point.
\end{itemize}

\paragraph{2. Totally Disconnected:}
A topological space is totally disconnected if its only connected components are singletons.
\begin{itemize}
    \item The space $\{0, 1\}$ with the discrete topology is clearly totally disconnected.
    \item A fundamental property of topology is that the product of any family of totally disconnected spaces is itself totally disconnected. 
    \item Since $X = \prod_{n=1}^\infty \{0, 1\}$ is a product of totally disconnected spaces, $X$ is totally disconnected. 
    \item Because $\mathcal{C}$ is homeomorphic to $X$, the Cantor set $\mathcal{C}$ is also totally disconnected.
\end{itemize}
In other words, for any distinct $x, y \in \mathcal{C}$, their images $e(x)$ and $e(y)$ must differ at some coordinate $k$. The set of all sequences whose $k$-th coordinate matches $e(x)_k$ is a clopen (closed and open) set containing $x$ but not $y$, which implies $x$ and $y$ cannot belong to the same connected component.
\end{proof}

\begin{theorem}[functionField_isFractionRing_of_affine] Let $R$ be an integral domain. Then the function field of the affine scheme $\operatorname{Spec} R$ is isomorphic to the field of fractions of $R$. \end{theorem}
\begin{proof}
By definition,  the function field is the stalk of the structure sheaf at  the generic point. But the generic point of $\operatorname{Spec} R$ corresponds to the zero ideal, and the stalk at the generic point is the localization of $R$ at the zero prime ideal, which is precisely the field of fractions of $R$.
\end{proof}

\begin{theorem}[isDominant_iff_forall_genericPoints_mem_fiber]
Let \(f : X \to Y\) be a quasi-compact morphism. Then, \(f\) is dominant if and only if for every generic point \(y\) of an irreducible component of \(Y\), the fiber \(f^{-1}(y)\) contain the generic point of an irreducible component of \(X\).
\end{theorem}
\begin{proof}
It is immediate that the condition is sufficient even without assuming \(f\) quasi-compact. To see that it is necessary, consider an affine open neighborhood \(U\) of \(y\); \(f^{-1}(U)\) is quasi-compact, hence a finite union of affine opens \(V_i\), and the hypothesis that \(f\) is dominant implies that \(y\) belongs to the closure in \(U\) of one of the \(f(V_i)\). One may clearly suppose \(X\) and \(Y\) reduced; since the closure in \(X\) of an irreducible component of \(V_i\) is an irreducible component of \(X\), one may replace \(X\) by \(V_i\), and \(Y\) by the reduced closed subscheme of \(U\) having \(\overline{f(V_i)}\cap U\) as underlying topological space, and one is thus reduced to proving the proposition when \(X=\mathrm{Spec}(A)\), \(Y=\mathrm{Spec}(B)\) are affine and reduced. Since \(f\) is dominant, \(B\) is then a subring of \(A\), and the proposition follows from the fact that every minimal prime ideal of \(B\) is the intersection of \(B\) with a minimal prime ideal of \(A\).
\end{proof}

\begin{definition}[FiniteType]
A morphism \(f : X \to Y\) is said to be \emph{of finite type} if \(Y\) is the union of a family \((V_\alpha)\) of affine open subsets having the following property:

\medskip

\noindent
(P) The inverse image \(f^{-1}(V_\alpha)\) is a finite union of affine open subsets \(U_{\alpha i}\) such that each of the rings \(\Gamma(U_{\alpha i},\mathcal O_X)\) is a finitely type \(\Gamma(V_\alpha,\mathcal O_Y)\)-algebra.

\medskip

In that case one also says that \(X\) is a scheme of finite type over \(Y\), or a \(Y\)-scheme of finite type.
\end{definition}

\begin{theorem}[hasPropertyP_of_finiteType]
    If \(f:X \to Y \) is a morphism of finite type, then every open affine subset \(W\) of \(Y\) has the property (P).
\end{theorem}
\begin{proof}
Let \(W\subseteq Y\) be an open affine. Then, \(W\) is quasi-compact. Therefore, \(W\) is covered by finitely many distinguished opens \(D(g_i)\subseteq V_{\alpha(i)}\), \( g_i\in \Gamma(V_{\alpha(i)},\mathcal O_Y)\), where each \(V_{\alpha(i)}\) belongs to the covering given by the definition. Fix one such distinguished open \(D(g)\subseteq V_\alpha\). By hypothesis, \(f^{-1}(V_\alpha)=\bigcup_j Z_j\) with \(Z_j\) affine and \(\Gamma(Z_j,\mathcal O_X)\) a finite type \(\Gamma(V_\alpha,\mathcal O_Y)\)-algebra. Let \(\varphi_j:\Gamma(V_\alpha,\mathcal O_Y)\to \Gamma(Z_j,\mathcal O_X)\) be the homomorphism induced by the restriction of \(f\) to \(Z_j\), and put \(g_j=\varphi_j(g)\). Then \(f^{-1}(D(g))\cap Z_j=D(g_j)\), and \(\Gamma(D(g_j),\mathcal O_X) = \Gamma(Z_j,\mathcal O_X)_{g_j} = \Gamma(Z_j,\mathcal O_X)[1/g_j]\). Hence, \(\Gamma(D(g_j),\mathcal O_X)\) is a finite type algebra over \(\Gamma(V_\alpha,\mathcal O_Y)[1/g] = \Gamma(D(g),\mathcal O_Y)\). Thus \(D(g)\) has the property (P). Since the \(D(g_i)\) form a finite affine cover of \(W\), it follows that \(W\) itself has the property \((P)\).
\end{proof}

\begin{theorem}[immersion_is_of_finiteType]
Let \(f : X \to Y\) be an immersion. If the underlying space of \(Y\) (resp. of \(X\)) is locally noetherian (resp. noetherian), then \(f\) is of finite type.
\end{theorem}

\begin{proof}
One may always suppose \(Y\) is affine by the lemma; if the underlying space of \(Y\) is locally noetherian, one may moreover suppose it is noetherian, since the underlying space of \(X\), being a subspace of it, is then noetherian. Otherwise, one may suppose \(Y\) is affine and the underlying space of \(X\) noetherian; then \(X\) admits a finite covering by affine opens \(D(g_i)\subset X\), \(g_i\in \Gamma(Y,\mathcal{O}_Y)\), each \(X\cap D(g_i)\) being closed in \(D(g_i)\) (hence an affine scheme), since \(X\) is locally closed in \(Y\). Therefore, \(\Gamma(X\cap D(g_i),\mathcal{O}_Y)\) is a finite type algebra over \(\Gamma(D(g_i),\mathcal{O}_Y)\), and thus \(X\cap D(g_i)\to D(g_i)\) is of finite type. Finally, \(\Gamma(D(g_i),\mathcal{O}_Y)=\Gamma(Y,\mathcal{O}_Y)_{g_i}=\Gamma(Y,\mathcal{O}_Y)[1/g_i]\), which is of finite type over \(\Gamma(Y,\mathcal{O}_Y)\), and this completes the proof.
\end{proof}

\begin{theorem}[isAffineOpen_inf_preimage]
Let \(Y\) be a separated scheme, and let \(f:X\to Y\) be a morphism. For every affine open subset \(U\) of \(X\) and every affine open subset \(V\) of \(Y\), \(U\cap f^{-1}(V)\) is affine.
\end{theorem}

\begin{proof}
Let \(p_1,p_2\) be the projections of \(X\times_{\mathbb Z}Y\). The subspace \(U\cap f^{-1}(V)\) is the image under \(p_1\) of \(\Gamma_f(X)\cap p_1^{-1}(U)\cap p_2^{-1}(V)\). Now \(p_1^{-1}(U)\cap p_2^{-1}(V)\) is identified with the underlying space of the scheme \(U\times_{\mathbb Z}V\), and is therefore an affine scheme. Since \(\Gamma_f\) is closed in
\(X\times_{\mathbb Z}Y\), the intersection \(\Gamma_f(X)\cap p_1^{-1}(U)\cap p_2^{-1}(V)
\) is closed in \(U\times_{\mathbb Z}V\). Consequently, the scheme induced by the subscheme of \(X\times_{\mathbb Z}Y\) associated with \(\Gamma_f\), on the open subset \(\Gamma_f(X)\cap p_1^{-1}(U)\cap p_2^{-1}(V)\) of its underlying space, is a closed subscheme of an affine scheme, hence is affine. The theorem then follows from the fact that \(\Gamma_f\) is an immersion.
\end{proof}

\begin{theorem}[isAffineHom_of_isAffineHom_struct_of_isAffineHom_diagonal] Let $g:X \to Y$ be a morphism of schemes over $S$. If $X$ is affine over $S$ and the diagonal map $\Delta:Y \to Y \times_S Y$ is affine, then $g$ is affine.
\end{theorem}
\begin{proof}
    The base change \(X\times_S Y \to Y\) of \(X \to S\) by \(Y \to S\) is affine since the affine morphisms are stable under base change. The morphism \((1,g):X \to X \times_S Y\) is the base change of \(\Delta:Y \to Y\times_S Y\) by the morphism \(X \times_S Y \to Y\times_SY\). Hence, it is affine. Now the result follows since the composition of affine morphisms is affine.
\end{proof}

\begin{definition}[IsQuasiFiniteModule] Given a local ring $A$ with the maximal ideal \(\mathfrak{m}\), we say that an \(A\)-module \(M\) is quasi-finite over \(A\) if \(M/\mathfrak{m} M \) has finite rank over the residue field \(k = A/\mathfrak{m}\).
\end{definition}
\begin{theorem}[isolated_in_fiber_iff_stalk_quasiFinite]
Let \(f:X\to Y\) be a morphism locally of finite type, and let \(x\) be a point of \(X\). The following conditions are equivalent:
\begin{enumerate}[label=(\alph*)]
    \item The point \(x\) is isolated in its fiber \(f^{-1}(f(x))\).
    \item The ring \(\mathcal O_x\) is a quasi-finite \(\mathcal O_{f(x)}\)-module \((0,7.4.1)\).
\end{enumerate}
\end{theorem}

\begin{proof}
The question being evidently local on \(X\) and on \(Y\), one may suppose \(X=\mathrm{Spec}(A)\) and \(Y=\mathrm{Spec}(B)\) affine, \(A\) being a \(B\)-algebra of finite type. Moreover, one may replace \(X\) by \(X\times_Y\mathrm{Spec}(\mathcal O_{f(x)})\) without changing the fiber \(f^{-1}(f(x))\) nor the local ring \(\mathcal O_x\); thus one may suppose that \(B\) is a local ring, equal to \(\mathcal O_{f(x)}\).

If \(\mathfrak n\) is the maximal ideal of \(B\), then \(f^{-1}(f(x))\) is an affine scheme with ring \(A/\mathfrak n A\), of finite type over \(k(f(x))=B/\mathfrak n\). This being so, if \((a)\) holds, one may moreover suppose that \(f^{-1}(f(x))\) is reduced to the point \(x\); hence \(A/\mathfrak n A\) is of finite rank over \(B/\mathfrak n\), in other words \(A\) is a quasi-finite \(B\)-module.

Conversely, if (b) holds, \(f^{-1}(f(x))\) is an affine Artinian scheme, hence discrete; consequently \(x\) is isolated in its fiber \(f^{-1}(f(x))\).
\end{proof}

\begin{theorem}
Let \(f:X\to Y\) be a morphism, and let \((U_\alpha)\) be an open covering of \(Y\) such that each \(U_\alpha\) is quasi-separated. Then, \(f\) is quasi-separated if and only if every \(f^{-1}(U_\alpha)\) is quasi-separated.
\end{theorem}
\begin{proof}
The inverse image in \(X\times_Y X\) of \(U_\alpha\) is \(X_\alpha\times_{U_\alpha}X_\alpha\), where \(X_\alpha=f^{-1}(U_\alpha)\), and the restriction \(X_\alpha\to X_\alpha\times_{U_\alpha}X_\alpha\) of \(\Delta_f\) is nothing other than \(\Delta_{f_\alpha}\), where \(f_\alpha\) denotes the restriction \(X_\alpha\to U_\alpha\) of \(f\). By Definition of quasi-separated morphisms and the local character of the notion of a quasi-compact morphism, in order for \(f\) to be quasi-separated, it is necessary and sufficient that each of the morphisms \(f_\alpha\) be so. But since, by hypothesis, the morphism \(U_\alpha\to \mathrm{Spec}(\mathbb Z)\) is quasi-separated, it is equivalent to say that \(f_\alpha\) is quasi-separated or that the composite \(X_\alpha\xrightarrow{f_\alpha}U_\alpha\to \mathrm{Spec}(\mathbb Z)\) is quasi-separated. This proves the proposition.
\end{proof}

\begin{theorem}[toΓSpec] Let $X$ be a scheme. There is a  canonical morphism $\varphi : X \to \mathrm{Spec}\Gamma(X)$ from $X$ to the spectrum of its global sections  where the underlying continuous map is given by sending a point $x \in X$ to the prime ideal $p$ of global sections that do not map to units in the stalk of the structure sheaf at $x$. 
\end{theorem}
\begin{proof}
  Let $x \in X$ and $U$ be an affine open neighborhood of $x$. Consider the ring homomorphism $\Gamma(X) \to \Gamma(U) \to \mathcal O_{X,x}$ given by restriction and taking germs at $x$.
  Let \[
p
\;=\;
\{\, s \in \Gamma(X) \mid s_x \text{ is not a unit in } \mathcal O_{X,x} \,\}.
\]
 We need to show that the induced map $\varphi^\sharp_x : (\Gamma(X) - p)^{-1} \Gamma(X) \to \mathcal O_{X,x}$ is local. Let $ t \in (\Gamma(X) - p)^{-1} \Gamma(X)$ which can be written as $r/s$ for some $s \not\in p$. We claim that $t \in  (\Gamma(X) - p)^{-1}p$ if and only if its germ $t_x$ is not a unit in $\mathcal O_{X,x}$. If $t \in  (\Gamma(X) - p)^{-1}p$, then $r \in p$ and $r_x$ is not a unit hence $t_x$ is not a unit in $\mathcal O_{X,x}$. Conversely, if $t_x$ is not a unit in $\mathcal O_{X,x}$, then $r_x$ is not a unit in $\mathcal O_{X,x}$ and hence $r \in p$ by definition.


\end{definition}

