\begin{theorem}[monges_circle_theorem]\label{thm:monge}
Monge's theorem states that for any three circles in a plane, none of which is completely inside one of the others, the intersection points of each of the three pairs of external tangent lines are collinear.

In this formalization, we consider the affine-plane case where the three radii are pairwise distinct, so that these intersection points are finite points rather than points at infinity. Degenerate circles of radius zero are allowed, provided the radii remain pairwise distinct.

For any two circles in a plane, an external tangent is a line that is tangent to both circles but does not pass between them. There are two such external tangent lines for any two circles satisfying the above non-containment assumptions. Monge's theorem states that the three such points given by the three pairs of circles lie on a straight line.
\end{theorem}

\begin{theorem}[napoleons_theorem_inner]\label{thm:napoleon_inner}
Let $A,B,C$ be non-collinear points in the plane.
On each side of $\triangle ABC$, construct an equilateral triangle \emph{internally} (all three on the same ``inner'' side).
Let $X,Y,Z$ be the centroids of the equilateral triangles on $AB,BC,CA$, respectively.
Then $\triangle XYZ$ is equilateral.
\end{theorem}

\begin{theorem}[napoleons_theorem_outer]\label{thm:napoleon_outer}
Let $A,B,C$ be non-collinear points in the plane.
On each side of $\triangle ABC$, construct an equilateral triangle \emph{externally} (all three on the same ``outer'' side).
Let $X,Y,Z$ be the centroids of the equilateral triangles on $AB,BC,CA$, respectively.
Then $\triangle XYZ$ is equilateral.
\end{theorem}

\begin{theorem}[brahmagupta_formula]\label{thm:brahmagupta_formula}
In Euclidean geometry, Brahmagupta's formula gives the area $K$ of a convex cyclic quadrilateral (a quadrilateral inscribed in a circle) given the lengths of its sides. 
Formally, let $A, B, C, D$ be the vertices of a convex cyclic quadrilateral in order. Let $a = |AB|, b = |BC|, c = |CD|$, and $d = |DA|$ be the lengths of the sides, and let $s$ be the semiperimeter, defined as:
\[
s = \frac{a + b + c + d}{2}
\]
Then the area $K$ of the quadrilateral is given by:
\[
K = \sqrt{(s - a)(s - b)(s - c)(s - d)}
\]
\end{theorem}

\begin{theorem}[smooth_function_separating_closed_sets]
Suppose $A$ and $B$ are disjoint closed subsets of a smooth manifold $M$. Show that there exists $f \in C^\infty(M)$ such that $0 \le f(x) \le 1$ for all $x \in M$, $f^{-1}(0) = A$, and $f^{-1}(1) = B$.
\end{theorem}

\begin{proof}
To construct such a function, we rely on the property that for any closed subset $K \subseteq M$, there exists a smooth nonnegative function $g: M \to \mathbb{R}$ such that $g^{-1}(0) = K$ (this is a known result from the theory of smooth partitions of unity, often labeled as Theorem 2.29 in this text).

Let $A$ and $B$ be disjoint closed subsets of $M$.
\begin{enumerate}
    \item By the aforementioned result, there exists a smooth function $g_A \in C^\infty(M)$ such that $g_A(x) \ge 0$ for all $x \in M$ and $g_A^{-1}(0) = A$.
    \item Similarly, there exists a smooth function $g_B \in C^\infty(M)$ such that $g_B(x) \ge 0$ for all $x \in M$ and $g_B^{-1}(0) = B$.
\end{enumerate}

Now, consider the function $f: M \to \mathbb{R}$ defined by:
\[
f(x) = \frac{g_A(x)}{g_A(x) + g_B(x)}.
\]

First, we check that the denominator $g_A(x) + g_B(x)$ is never zero. Since $A \cap B = \emptyset$, for any $x \in M$, $x$ cannot be in both $A$ and $B$. 
\begin{itemize}
    \item If $x \notin A$, then $g_A(x) > 0$.
    \item If $x \in A$, then $x \notin B$, so $g_B(x) > 0$.
\end{itemize}
In either case, $g_A(x) + g_B(x) > 0$ for all $x \in M$. Thus, $f$ is well-defined. Since $g_A$ and $g_B$ are smooth and their sum is non-zero, $f$ is a smooth function, i.e., $f \in C^\infty(M)$.

Next, we verify the required properties:
\begin{itemize}
    \item \textbf{Range:} Since $g_A(x) \ge 0$ and $g_B(x) \ge 0$, it follows that $0 \le \frac{g_A(x)}{g_A(x) + g_B(x)} \le 1$.
    \item \textbf{Preimage of 0:} $f(x) = 0$ if and only if $g_A(x) = 0$. By construction, $g_A(x) = 0 \iff x \in A$. Thus, $f^{-1}(0) = A$.
    \item \textbf{Preimage of 1:} $f(x) = 1$ if and only if $g_A(x) = g_A(x) + g_B(x)$, which implies $g_B(x) = 0$. By construction, $g_B(x) = 0 \iff x \in B$. Thus, $f^{-1}(1) = B$.
\end{itemize}
Therefore, $f$ is the desired smooth function.
\end{proof}

\begin{theorem}[tangentBundleProdDiffeomorph]
Prove that if $M$ and $N$ are smooth manifolds, then $T(M \times N)$ is diffeomorphic to $TM \times TN$.
\end{theorem}

\begin{theorem}
$T\mathbb{S}^1$ is diffeomorphic to $\mathbb{S}^1 \times \mathbb{R}$.
\end{theorem}

\begin{theorem}[isInteriorPoint_of_bijective_mfderiv]
Suppose $M$ is a smooth manifold (without boundary), $N$ is a smooth manifold with boundary, and $F: M \to N$ is smooth. Show that if $p \in M$ is a point such that $dF_p$ is nonsingular, then $F(p) \in \operatorname{Int} N$.
\end{theorem}

\begin{theorem}[gamma_not_smooth_embedding]
Let $\gamma: \mathbb{R} \to \mathbb{R}^2$ be the map $\gamma(t) = (t^3, 0)$. Show that $\gamma$ is a smooth map and a topological embedding, but it is not a smooth embedding.
\end{theorem}

\begin{theorem}[affineSubspace_image_of_linear_constraints]
\textbf{Affine set.} Show that the set $\{Ax + b \mid Fx = g\}$ is affine. Here $A \in \mathbb{R}^{m \times n}$, $b \in \mathbb{R}^m$, $F \in \mathbb{R}^{p \times n}$, and $g \in \mathbb{R}^p$.
\end{theorem}

\begin{proof}
A set $S$ is affine if for every $z_1, z_2 \in S$ and $\theta \in \mathbb{R}$, the point $\theta z_1 + (1 - \theta)z_2$ is also in $S$.

Let $S = \{Ax + b \mid Fx = g\}$. Suppose $z_1, z_2 \in S$. Then there exist $x_1, x_2 \in \mathbb{R}^n$ such that:
\begin{align*}
z_1 &= Ax_1 + b, \quad Fx_1 = g \\
z_2 &= Ax_2 + b, \quad Fx_2 = g
\end{align*}
Now, for any $\theta \in \mathbb{R}$, consider the affine combination:
\begin{align*}
\theta z_1 + (1 - \theta)z_2 &= \theta(Ax_1 + b) + (1 - \theta)(Ax_2 + b) \\
&= A(\theta x_1 + (1 - \theta)x_2) + (\theta + (1 - \theta))b \\
&= A(\theta x_1 + (1 - \theta)x_2) + b.
\end{align*}
Let $\bar{x} = \theta x_1 + (1 - \theta)x_2$. We then check the condition $F\bar{x} = g$:
\[
F\bar{x} = F(\theta x_1 + (1 - \theta)x_2) = \theta Fx_1 + (1 - \theta)Fx_2 = \theta g + (1 - \theta)g = g.
\]
Since $\theta z_1 + (1 - \theta)z_2 = A\bar{x} + b$ with $F\bar{x} = g$, it follows that $\theta z_1 + (1 - \theta)z_2 \in S$. Therefore, $S$ is affine.
\end{proof}

\begin{theorem}[exists_smooth_vectorField_on_graph]
Let $M$ be a smooth manifold with or without boundary, let $N$ be a smooth manifold, and let $f: M \to N$ be a smooth map. Define $F: M \to M \times N$ by $F(x) = (x, f(x))$. For every $X \in \mathfrak{X}(M)$, there is a smooth vector field $Y$ on $M \times N$ that is $F$-related to $X$; that is, $dF_p(X_p) = Y_{F(p)}$ for every $p \in M$.
\end{theorem}

\begin{theorem}[global_integralCurve_unique_fundamental_period]
Suppose $M$ is a smooth manifold, $X \in \mathfrak{X}(M)$, and $\gamma: \mathbb{R} \to M$ is a global integral curve of $X$. We say $\gamma$ is \textbf{periodic} if there is a number $T > 0$ such that $\gamma(t + T) = \gamma(t)$ for all $t \in \mathbb{R}$. Show that if $\gamma$ is periodic and nonconstant, then there exists a unique positive number $T$ (called the \textbf{period} of $\gamma$) such that $\gamma(t) = \gamma(t')$ if and only if $t - t' = kT$ for some $k \in \mathbb{Z}$.
\end{theorem}

\begin{theorem}[morleys_trisector_theorem]\label{thm:morley_trisector}
In plane geometry, Morley's trisector theorem states that in any triangle, the three points of intersection of the adjacent angle trisectors form an equilateral triangle, called the \textbf{first Morley triangle}.

Formally, let $X, Y, Z$ be the intersections of the adjacent internal angle trisectors of a triangle $ABC$. Then the triangle $XYZ$ is equilateral.
\end{theorem}

\begin{definition}[LCM]
Define \(\text{LCM}(m)\) as the least common multiple of all positive integers up to a given natural number \( m \).
\end{definition}

\begin{lemma}[LCM_gt_0]
For any natural number \( m \), the least common multiple \( \text{LCM}(m) \) is greater than zero.
\end{lemma}
\begin{proof}
We unfold the definition of \( \text{LCM} \) and use logical simplifications to reduce the statement to basic properties of natural numbers. The key steps involve showing that the least common multiple cannot be zero, as it is defined over positive integers and their multiples. The simplification tactic resolves the inequality \( \text{LCM}(m) > 0 \) by verifying that zero cannot be the least common multiple of any natural number \( m \).
\end{proof}

\begin{lemma}[LCM_monotone]
For all natural numbers \( m \le n \), \( \mathrm{LCM}(m) \le \mathrm{LCM}(n) \).
\end{lemma}
\begin{proof}
We verify monotonicity by showing \( \mathrm{LCM}(n) \mid \mathrm{LCM}(n+1) \). For \( n > 0 \), the interval \( [1, n] \) is contained in \( [1, n+1] \), so the least common multiple over the larger set is divisible by the smaller one. For \( n = 0 \), we directly confirm \( \mathrm{LCM}(0) = 1 \le \mathrm{LCM}(1) = 1 \).
\end{proof}

\begin{lemma}[LCM_dvd_by]
For natural numbers \( m \) and \( n \) with \( 1 \leq m \leq n \), the product \( m \cdot \binom{n}{m} \) divides the least common multiple \( \mathrm{LCM}(1, 2, \dots, n) \). That is, \( m \cdot \binom{n}{m} \mid \mathrm{LCM}(n) \).
\end{lemma}
\begin{proof}
We begin by defining a function \( \beta'(m, n) \) as the integral \( \int_0^1 x^{m-1}(1-x)^{n-m} \, dx \), which is known to equal \( \frac{1}{m \cdot \binom{n}{m}} \). This is established using properties of the Gamma function and factorial identities.

Next, we expand \( \beta'(m, n) \) into a sum involving rational coefficients divided by integers from 1 to \( n \). This expansion is achieved by expressing the integrand as a polynomial, applying the binomial theorem, and integrating term-by-term. The result is a sum of the form \( \sum_{i=1}^n \frac{a_i}{i} \), where \( a_i \) are integers derived from binomial coefficients and powers of \( -1 \).

By equating the two expressions for \( \beta'(m, n) \), we find that \( \frac{1}{m \cdot \binom{n}{m}} = \sum_{i=1}^n \frac{a_i}{i} \). Multiplying both sides by \( m \cdot \binom{n}{m} \cdot \mathrm{LCM}(n) \), we obtain an integer linear combination of terms \( \mathrm{LCM}(n) \cdot \frac{a_i}{i} \), which are integers due to the divisibility of \( \mathrm{LCM}(n) \) by all \( i \in \{1, \dots, n\} \).

This implies that \( m \cdot \binom{n}{m} \) divides \( \mathrm{LCM}(n) \), completing the proof.
\end{proof}

\begin{lemma}[LCM_range_lower_bdd]
For all natural numbers \( m \geq 7 \), the least common multiple of the numbers from \( 1 \) to \( m \) satisfies \( \mathrm{LCM}(m) \geq 2^m \).
\end{lemma}
\begin{proof}
We proceed by case analysis on \( m \). For \( m < 9 \), we directly verify the inequality for \( m = 7 \) and \( m = 8 \) using computational checks. For \( m \geq 9 \), we consider two subcases based on the parity of \( m \).

For the odd case \( m = 2k + 1 \), we establish the inequality \( 2^{2k+2} \leq \mathrm{LCM}(2k+1) \) using properties of binomial coefficients and the fact that certain products divide \( \mathrm{LCM}(2k+1) \). Specifically, we show that \( k \cdot (k+1) \cdot \binom{2k+1}{k} \) divides \( \mathrm{LCM}(2k+1) \), and use this to derive the required bound.

For the even case \( m = 2k \), we reduce it to the odd case by showing that \( \mathrm{LCM}(2k) \geq \mathrm{LCM}(2l+1) \) for an appropriate \( l \), and then apply the previously established bound for the odd case.

The key steps involve bounding the sum of binomial coefficients, using monotonicity of the LCM function, and applying properties of divisibility and coprimality to combine bounds from multiple divisors.
\end{proof}

\begin{theorem}
Suppose that $I = \langle x^\alpha \mid \alpha \in A \rangle$ is a monomial ideal, and let $S$ be the set of all exponents that occur as monomials of $I$. Then, for any monomial order $>$, prove that the smallest element of $S$ with respect to $>$ must lie in $A$.
\end{theorem}

\begin{theorem}
Let $k$ be an arbitrary field and let $S$ be the subset of all polynomials in $k[x_1,\dots,x_n]$ that have no zeros in $k^n$. If $I$ is any ideal in $k[x_1,\dots,x_n]$ such that $I \cap S=\varnothing$, then $\mathbf V(I)\neq\varnothing$.
\end{theorem}

\begin{theorem}
Given polynomials $f,g,h$ in $k[x_1,\dots,x_n]$, where
$h=\gcd(f,g)$ means that $h$ divides both $f$ and $g$ and is divisible by every common divisor of
$f$ and $g$, prove that $h=\gcd(f,g)$ if and only if $\langle h\rangle$ is the smallest
principal ideal containing $\langle f,g\rangle$.
\end{theorem}

\begin{theorem}
Let $k$ be an arbitrary field and let $I,J$ be ideals in $k[x_1,\ldots,x_n]$.
Then
\begin{enumerate}
  \item $\sqrt{IJ} = \sqrt{I \cap J}$.

  \item In $k[x,y]$, let $I=\langle x\rangle$ and $J=\langle x,y\rangle$.
  Show that $I$ and $J$ are radical ideals, but $IJ$ is not a radical ideal.

  \item In $k[x,y]$, with $I=\langle x\rangle$ and $J=\langle x,y\rangle$ as above,
  show that $\sqrt{IJ} \neq \sqrt{I}\,\sqrt{J}$.
\end{enumerate}
\end{theorem}

\begin{theorem}[zeroLocus_mul]
If $I$ and $J$ are ideals in $k[x_1, \dots, x_n]$, then $\mathbf{V}(I \cdot J) = \mathbf{V}(I) \cup \mathbf{V}(J)$.
\end{theorem}

\begin{proof}
Let $a \in \mathbf{V}(I \cdot J)$. Then $g(a)h(a) = 0$ for all $g \in I$ and all $h \in J$. If $g(a) = 0$ for all $g \in I$, then $a \in \mathbf{V}(I)$. If $g(a) \neq 0$ for some $g \in I$, then we must have $h(a) = 0$ for all $h \in J$. In either event, $a \in \mathbf{V}(I) \cup \mathbf{V}(J)$.

Conversely, suppose $a \in \mathbf{V}(I) \cup \mathbf{V}(J)$. Either $g(a) = 0$ for all $g \in I$ or $h(a) = 0$ for all $h \in J$. Thus, $g(a)h(a) = 0$ for all $g \in I$ and $h \in J$. Thus, $f(a) = 0$ for all $f \in I \cdot J$ and, hence, $a \in \mathbf{V}(I \cdot J)$.
\end{proof}

\begin{theorem}[zariskiClosure_is_smallest_algebraic_set]
If $S \subseteq k^n$, the affine algebraic set $\mathbf{V}(\mathbf{I}(S))$ is the \emph{smallest algebraic set that contains} $S$ [in the sense that if $W \subseteq k^n$ is any affine algebraic set containing $S$, then $\mathbf{V}(\mathbf{I}(S)) \subseteq W$].
\end{theorem}

\begin{proof}
If $W \supseteq S$, then $\mathbf{I}(W) \subseteq \mathbf{I}(S)$ because $\mathbf{I}$ is inclusion-reversing. But then $\mathbf{V}(\mathbf{I}(W)) \supseteq \mathbf{V}(\mathbf{I}(S))$ because $\mathbf{V}$ also reverses inclusions. Since $W$ is an affine algebraic set, $\mathbf{V}(\mathbf{I}(W)) = W$ by The Ideal–Variety Correspondence, and the result follows.
\end{proof}

\begin{theorem}[span_pow_card_mul_le_span_image_pow]
Let $s=\{g_1,\dots,g_r\}$ be a finite subset of $k[x_1,\dots,x_n]$.
Set $J := \langle s\rangle$ and let $M\ge 0$. Then
\[
  J^{\,rM}
  \;\subseteq\;
  \left\langle\, g^M \mid g\in s \,\right\rangle.
\]
\end{theorem}
